<script setup lang="ts">
import { onMounted,ref } from 'vue'
import { foundation,openDocument,type StudyTask,type DailyPlan } from '@/api/foundation'
import GeneratePractice from '@/components/GeneratePractice.vue'
import { messageOf } from '@/api/client'
const tasks=ref<StudyTask[]>([]),busy=ref(false),error=ref('')
const plan=ref<DailyPlan|null>(null)
async function action(fn:()=>Promise<unknown>){busy.value=true;error.value='';try{await fn();[tasks.value,plan.value]=await Promise.all([foundation.tasks(),foundation.dailyPlan()])}catch(e){error.value=messageOf(e)}finally{busy.value=false}}
onMounted(()=>action(async()=>{}))
</script>
<template><div><header class="page-head"><div><h1>我的学习任务</h1><p>结合有效作答、规则复习间隔、难度来源和每日预算安排学习；推荐策略尚未经过学习效果校准。</p></div><button class="primary" :disabled="busy" @click="action(foundation.generate)">生成今日计划</button></header><div v-if="error" class="notice error" role="alert">{{error}}</div><section v-if="plan" class="card section"><h2>今日计划 · {{plan.Date}}</h2><p>已安排 {{plan.AllocatedMinutes}} / {{plan.BudgetMinutes}} 分钟（预计用时，包含今日已完成任务）</p><p class="muted">按北京时间划分每日计划；当天预算首次生成后固定，问卷修改从次日生效。重复生成保留已有任务和完成状态。</p></section><GeneratePractice/><section class="card"><div v-if="!tasks.length" class="empty"><h2>暂无可推荐的学习任务</h2><p>请准备可用题目或学习资源；未测知识点可以安排基础学习，没有资源时不会凭空生成任务。</p><RouterLink to="/exam408/assessment">前往测评</RouterLink></div><article v-for="t in tasks" :key="t.ID" class="card section"><h2>{{t.Title}} <span class="pill">{{t.Completed?'已完成':'待学习'}}</span></h2><p>{{t.Reason}}</p><p>{{t.PlanDate?`计划日期：${t.PlanDate}`:"历史任务"}} · 预计 {{t.EstimatedMinutes||"未设定"}} 分钟{{t.DurationSource==="video_segment"?"（视频片段时长）":"（估计值）"}}</p><p v-if="t.Kind==='video'">建议从 {{t.StartSeconds}} 秒开始{{t.EndSeconds?'，至 '+t.EndSeconds+' 秒':''}}</p><div class="toolbar-actions"><a v-if="t.URL" :href="t.URL" target="_blank" rel="noopener noreferrer" class="secondary">打开学习资源</a><button v-if="t.DocumentID" class="secondary" @click="action(()=>openDocument(t.DocumentID,t.Page))">查看教材原文</button><RouterLink v-if="t.Kind==='question'" class="secondary" :to="{path:'/exam408/assessment',query:{point:t.PointID,asset:t.AssetID}}">练习这道题</RouterLink><button v-if="!t.Completed" class="primary" :disabled="busy" @click="action(()=>foundation.complete(t.ID))">标记完成</button><RouterLink v-else class="secondary" :to="{path:'/exam408/assessment',query:{point:t.PointID}}">新题复测</RouterLink></div><p class="muted">标记完成只记录学习进度，不直接增加掌握度。</p></article></section></div></template>
